# Initially generated by GitHub Copilot.
from functools import reduce
from mb_cmn import template_names as tmpln
from foi import foi_gray_marks as gray_marks
from foi import foi_wikitext_helpers as fwh
from foi import foi_dual_ml_helpers as dml
from foi import foi_struct as fct
from mb_cmn.my_utils import sl_map


def find_fois_wt(mroge):
    """Find "dual mater lectionis" involving alef."""
    return fwh.find_fois_by_forms_in_minirow_ep(_FOILERS, mroge)


def _find_fois_in_string(stack, string):
    # A documentation note's body is not searched at any depth: a string in a template
    # inside the body is skipped as well as one directly in it.  The spellings quoted
    # in scroll-difference notes are searched, and their rows say scrdfftar-note.  Ben
    # chose both on 2026-11-12 (S1 of the 2026-11-11 audit in
    # doc/blind-dive-into-template-params-update.md); until then only a string directly
    # in a note's body was skipped.
    if "doc-part-n" in stack:
        return []
    fois = reduce(_add_fois_in_str, fwh.forms(string), [])
    qual_fois = sl_map((_qualify, stack), fois)
    return qual_fois


def _add_fois_in_str(accum, form):
    # A form's features are found in its text, and its row shows its gray marks.
    target = gray_marks.target(form)
    fois_in_str = dml.find_fois_in_str(gray_marks.text(form))
    return accum + [(foi_path, target, *rest) for foi_path, _text, *rest in fois_in_str]


def _qualify(stack, unqual_foi):
    if len(unqual_foi) == 3:
        foi_path, unqual_target, found_qualifier = unqual_foi
    else:
        foi_path, unqual_target = unqual_foi
        found_qualifier = {}
    stack_summary = _stack_summary(stack)
    qualifier = {"stack_str": stack_summary}
    qualifier.update(found_qualifier)
    qual_target = fct.make_qtarget(unqual_target, qualifier)
    return foi_path, qual_target


def _stack_summary(stack):
    if stack in _STACK_SUMMARIES:
        return fwh.stack_summary(_STACK_SUMMARIES, stack)
    if stack and stack[-1] in _NOTE_STACK_PARTS:
        return stack[-1]
    return None


_FOILERS = fwh.all_branch_foilers(
    {
        str: _find_fois_in_string,
        tmpln.SLH_WORD: fwh.find_fois_in_slh_word_arg_1,
        "נוסח": fwh.label_args_of_doc,
        tmpln.SCRDFF_TAR: fwh.label_args_of_scrdfftar,
        tmpln.SCRDFF_NO_TAR: fwh.fail_on_unexpected_template_in_plus,
    }
)
_NOTE_STACK_PARTS = {"doc-part-n", "scrdfftar-note", tmpln.SLH_WORD}
_STACK_SUMMARIES = {
    tuple(): None,
    ("doc-target",): None,
    ("כו״ק",): None,
    ("קו״כ",): None,
    ("doc-target", "קו״כ"): None,
    ("doc-target", "כו״ק"): None,
    ("מ:דחי",): None,
    #
    ("doc-target", "scrdfftar-note"): -1,
    ("doc-part-n",): -1,
    ("doc-target", tmpln.SLH_WORD): -1,
}
